#include <iostream>
#include <iterator>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string raw((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    string st;
    for (char ch : raw) {
        if (ch != 'A' && ch != 'B' && ch != 'C' && ch != 'D') continue;
        // A/B and C/D cancel when adjacent, in either order.
        if (!st.empty() && st.back() != ch && ((st.back() <= 'B') == (ch <= 'B'))) st.pop_back();
        else st += ch;
    }
    cout << st << '\n';
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] raw = System.in.readAllBytes();
        byte[] st = new byte[raw.length];
        int top = 0;
        for (byte ch : raw) {
            if (ch < 'A' || ch > 'D') continue;
            // A/B and C/D cancel when adjacent, in either order.
            if (top > 0 && st[top - 1] != ch && ((st[top - 1] <= 'B') == (ch <= 'B'))) top--;
            else st[top++] = ch;
        }
        System.out.println(new String(st, 0, top));
    }
}

package main

import (
	"io"
	"os"
)

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	st := make([]byte, 0, len(raw)+1)
	for _, ch := range raw {
		if ch < 'A' || ch > 'D' {
			continue
		}
		// A/B and C/D cancel when adjacent, in either order.
		if n := len(st); n > 0 && st[n-1] != ch && (st[n-1] <= 'B') == (ch <= 'B') {
			st = st[:n-1]
		} else {
			st = append(st, ch)
		}
	}
	os.Stdout.Write(append(st, '\n'))
}
